```javascript
import { Group, Mesh, PlaneGeometry, CircleGeometry, Color, Vector3, AmbientLight, DirectionalLight, PointLight } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'feature-triptych';

  // Palette
  const palette = config.intent?.visualSpec?.colors ?? config.colors ?? {
    background: '#0b0b10', surface: '#16161d', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#191921' }, { at: 1, hex: '#121218' }]
  };
  const accentHex = palette.accent || '#ff2a38';
  const paperHex = palette.paper || '#e8ecf2';
  const stops = palette.gradientStops?.length ? palette.gradientStops : [{ at: 0, hex: '#191921' }, { at: 1, hex: '#121218' }];
  const topColor = new THREE.Color(stops[0].hex);
  const bottomColor = new THREE.Color(stops[stops.length - 1].hex);
  const borderHex = '#26262f';

  // Lighting (node-local) — key upper-left + rim right + ambient fill
  const ambient = new AmbientLight(0xffffff, 0.55);
  group.add(ambient);

  const keyLight = new DirectionalLight(0xffffff, 1.15);
  keyLight.position.set(-3.2, 3.4, 4.0);
  group.add(keyLight);

  const rimLight = new DirectionalLight(new THREE.Color(accentHex), 0.6);
  rimLight.position.set(3.5, -1.5, 2.5);
  group.add(rimLight);

  const fillLight = new PointLight(0xffffff, 0.35, 18, 1.5);
  fillLight.position.set(0, -1.8, 3.2);
  group.add(fillLight);

  // Text content items (per card)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  // Expect 9 items in groups of 3: glyph, title, body
  const cards = [];
  for (let i = 0; i < 3; i++) {
    cards.push({
      glyph: items[i * 3]?.text ?? String(i + 1).padStart(2, '0'),
      title: items[i * 3 + 1]?.text ?? '',
      body: items[i * 3 + 2]?.text ?? ''
    });
  }

  // Card dimensions
  const cardW = 1.5;
  const cardH = 1.9;
  const gap = 0.25;
  const rowTotal = 3 * cardW + 2 * gap; // 5.0
  const startX = -rowTotal / 2 + cardW / 2;

  // Text sizing (scene units — em heights from spec scaled to fit)
  // Card title 20px ~ 0.13 scene; body 13px ~ 0.083; glyph 20px mono ~ 0.11
  const titleFontSize = 26;
  const bodyFontSize = 15;
  const glyphFontSize = 24;

  // Disposal registry
  const disposables = [];
  const timelines = [];

  function disposeNode(n) {
    if (n.geometry) disposables.push(n.geometry);
    if (n.material) disposables.push(n.material);
  }

  // Backdrop plane with vertical gradient (stage)
  const bgGeo = new PlaneGeometry(9, 6.5);
  const bgMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 1 });
  bgMat.colorNode = mix(vec3(topColor.r, topColor.g, topColor.b), vec3(bottomColor.r, bottomColor.g, bottomColor.b), uv().y);
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // Subtle floor contact-shadow band behind cards (depth plane)
  const floorGeo = new PlaneGeometry(8, 3.2);
  const floorMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.0 });
  // soft radial-ish via uv remap not strict — keep simple dark wash
  floorMat.colorNode = vec3(0.06, 0.06, 0.075);
  const floor = new Mesh(floorGeo, floorMat);
  floor.position.set(0, -1.6, -1.5);
  floor.rotation.x = -0.08;
  group.add(floor);
  disposables.push(floorGeo, floorMat);

  const cardObjects = [];

  for (let i = 0; i < 3; i++) {
    const cardGroup = new THREE.Group();
    cardGroup.position.set(startX + i * (cardW + gap), 0, 0);

    // --- Card body plane (PBR extruded feel via Standard material) ---
    const cardGeo = new PlaneGeometry(cardW, cardH, 1, 1);
    const cardMat = new MeshStandardNodeMaterial({
      metalness: 0.25,
      roughness: 0.6,
      clearcoat: 0.15,
      transparent: false
    });
    // vertical ramp via uv.y
    cardMat.colorNode = mix(
      vec3(topColor.r, topColor.g, topColor.b),
      vec3(bottomColor.r, bottomColor.g, bottomColor.b),
      smoothstep(0.0, 1.0, uv().y)
    );

    // Hairline border via UV edge mask
    const bW = 0.006;
    const edgeX = smoothstep(0.0, bW, uv().x).sub(smoothstep(1.0 - bW, 1.0, uv().x));
    const edgeY = smoothstep(0.0, bW, uv().y).sub(smoothstep(1.0 - bW, 1.0, uv().y));
    const borderMask = edgeX.min(edgeY).oneMinus();
    const borderCol = new THREE.Color(borderHex);
    cardMat.colorNode = mix(
      cardMat.colorNode,
      vec3(borderCol.r, borderCol.g, borderCol.b),
      borderMask
    );

    const cardMesh = new Mesh(cardGeo, cardMat);
    cardGroup.add(cardMesh);
    disposables.push(cardGeo, cardMat);

    // --- Contact shadow plane beneath card (widens/softens on hover) ---
    const shadowGeo = new PlaneGeometry(cardW * 1.1, cardH * 0.28);
    const shadowMat = new MeshBasicNodeMaterial({
      transparent: true,
      opacity: 0.45,
      depthWrite: false
    });
    // radial-ish vertical soft band using uv.y
    const sy = smoothstep(0.0, 0.5, uv().y).mul(smoothstep(1.0, 0.5, uv().y));
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0).mul(sy.mul(0.7).add(0.3));
    shadowMat.opacityNode = sy.mul(uniform(0.45));
    const shadow = new Mesh(shadowGeo, shadowMat);
    shadow.position.set(0, -cardH / 2 - 0.04, -0.02);
    shadow.rotation.x = -Math.PI / 2;
    cardGroup.add(shadow);
    disposables.push(shadowGeo, shadowMat);

    // --- Icon seat: machined disc extruded ---
    // Use a slightly extruded disc via circle + thin cylinder ring for bevel illusion
    const discGeo = new CircleGeometry(0.2, 48);
    const discMat = new MeshStandardNodeMaterial({
      metalness: 0.5,
      roughness: 0.55,
      clearcoat: 0.2
    });
    // brushed anisotropy proxy — slight emissive accent ring
    const discColor = new THREE.Color('#1c1c24');
    discMat.colorNode = vec3(discColor.r, discColor.g, discColor.b);
    const disc = new Mesh(discGeo, discMat);
    disc.position.set(0, cardH / 2 - 0.375 - 0.1, 0.04);
    cardGroup.add(disc);
    disposables.push(discGeo, discMat);

    // disc rim ring (thin accent ring around disc)
    const ringGeo = new THREE.RingGeometry(0.18, 0.205, 48);
    const ringMat = new MeshStandardNodeMaterial({
      metalness: 0.6, roughness: 0.4, clearcoat: 0.25
    });
    ringMat.colorNode = vec3(0.16, 0.16, 0.2);
    const ring = new Mesh(ringGeo, ringMat);
    ring.position.copy(disc.position);
    ring.position.z = 0.045;
    cardGroup.add(ring);
    disposables.push(ringGeo, ringMat);

    // --- Text: glyph (emissive accent) ---
    const glyphObj = ctx.fontAtlas.createText(cards[i].glyph, {
      fontSize: glyphFontSize, color: accentHex, align: 'center', letterSpacingPx: 0
    });
    // place on disc face
    glyphObj.position.set(disc.position.x, disc.position.y, disc.position.z + 0.05);
    // boost emissive feel: nest glyph inside a subtle accent halo plane
    cardGroup.add(glyphObj);

    // accent glow behind glyph
    const glowGeo = new CircleGeometry(0.16, 32);
    const glowMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.35, depthWrite: false });
    glowMat.colorNode = vec3(new THREE.Color(accentHex).r, new THREE.Color(accentHex).g, new THREE.Color(accentHex).b);
    const glow = new Mesh(glowGeo, glowMat);
    glow.position.copy(glyphObj.position);
    glow.position.z -= 0.005;
    cardGroup.add(glow);
    disposables.push(glowGeo, glowMat);

    // --- Text: title ---
    const titleObj = ctx.fontAtlas.createText(cards[i].title, {
      fontSize: titleFontSize, color: paperHex, align: 'center', letterSpacingPx: 0, maxWidthPx: 320
    });
    titleObj.position.set(0, disc.position.y - 0.2 - 0.25, 0.04);
    cardGroup.add(titleObj);

    // --- Text: body ---
    const bodyObj = ctx.fontAtlas.createText(cards[i].body, {
      fontSize: bodyFontSize, color: '#b9bdc7', align: 'center', letterSpacingPx: 0, maxWidthPx: 320
    });
    bodyObj.position.set(0, titleObj.position.y - 0.18, 0.04);
    cardGroup.add(bodyObj);

    group.add(cardGroup);
    cardObjects.push({
      group: cardGroup, mesh: cardMesh, shadow, disc, ring, glyph: glyphObj, glow,
      mat: cardMat, shadowMat, glowMat, ringMat
    });
  }

  // --- Mount stagger entrance: fade-up, 500ms, 80ms stagger ---
  const entrance = gsap.timeline();
  cardObjects.forEach((c, i) => {
    c.group.position.y = 0.2;
    // fade via material opacity (all are transparent-able). Use a tween on a proxy.
    const proxy = { op: 0 };
    entrance.to(proxy, {
      op: 1, duration: 0.5, ease: 'power2.out', delay: i * 0.08,
      onUpdate: () => {
        // apply to card material
        c.mat.transparent = true;
        c.mat.opacity = proxy.op;
        c.shadowMat.opacity = proxy.op * 0.45;
      }
    }, 0);
    entrance.to(c.group.position, {
      y: 0, duration: 0.5, ease: 'power2.out', delay: i * 0.08
    }, 0);
    // glow fade
    entrance.fromTo(c.glowMat, { opacity: 0 }, { opacity: 0.35, duration: 0.5, ease: 'power2.out', delay: i * 0.08 }, 0);
  });
  timelines.push(entrance);

  // --- Hover lift state (handlers attached; use pointer events via raycast externally)
  // We expose hover/click handlers on userData; the host raycaster will call them.
  const hoverStates = cardObjects.map(() => ({ hovering: false, tl: null }));

  function setHover(index, hovering) {
    const c = cardObjects[index];
    const st = hoverStates[index];
    if (st.tl) st.tl.kill();
    st.tl = gsap.timeline();
    st.hovering = hovering;
    st.tl.to(c.group.position, {
      y: hovering ? 0.06 : 0,
      z: hovering ? 0.12 : 0,
      duration: 0.18, ease: 'power2.out'
    }, 0);
    // shadow widens/softens
    st.tl.to(c.shadow.scale, {
      x: hovering ? 1.18 : 1.0,
      y: hovering ? 1.5 : 1.0,
      duration: 0.18, ease: 'power2.out'
    }, 0);
    // glyph emissive (proxy via glow opacity + ring emissive boost)
    const glowTarget = hovering ? 0.6 : 0.35;
    st.tl.to(c.glowMat, { opacity: glowTarget, duration: 0.18, ease: 'power2.out' }, 0);
    // accent ring brighter on hover
    st.tl.to(c.ringMat, {
      emissive: new THREE.Color(accentHex),
      emissiveIntensity: hovering ? 0.6 : 0.0,
      duration: 0.18, ease: 'power2.out'
    }, 0);
    // press scale settle when leaving
    if (!hovering) {
      st.tl.to(c.group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.12, ease: 'back.out(2)' }, 0);
    } else {
      st.tl.to(c.group.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.18, ease: 'power2.out' }, 0);
    }
    timelines.push(st.tl);
  }

  // Attach handlers
  group.userData.handlers = {
    onPointerOver: (e) => {
      const idx = cardObjects.findIndex(c => c.group === e.object?.parent || c.mesh === e.object || c.group === e.object);
      if (idx >= 0) setHover(idx, true);
    },
    onPointerOut: (e) => {
      const idx = cardObjects.findIndex(c => c.group === e.object?.parent || c.mesh === e.object || c.group === e.object);
      if (idx >= 0) setHover(idx, false);
    },
    onClick: (e) => {
      // emit navigation to features section
      ctx.emit('navigate', { to: 'hub-features' });
    }
  };

  // Apply cinematic primitives (none specified)
  const prims = config.cinematicPrimitives ?? [];
  const primHandles = [];
  for (const p of prims) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      const r = ctx.primitives[p.name](group, p.params);
      if (r) primHandles.push(r);
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach(t => { try { t.kill(); } catch (_) {} });
    primHandles.forEach(h => { try { h.cleanup?.(); } catch (_) {} });
    disposables.forEach(d => { try { d.dispose?.(); } catch (_) {} });
  };

  return group;
}
